spec.query:
from (bucket: "my-bucket")
  |> range(
       start: 0,
       stop: v.timeRangeStop
     )
  |> filter(
       fn: (r) => 
       r["_measurement"] == "utilities" and
       r["_field"] == "electricity_generation"
     )
  |> drop(
       columns: [
         "_measurement",
         "_field",
         "_start",
         "_stop",
         "source"
       ]
     )
  |> derivative(
       unit: 1d
     )
  |> rename(
       columns: {
         "_value": "daily_electricity_generation"
       }
     )

from (bucket: "my-bucket")
  |> range(
       start: 0,
       stop: v.timeRangeStop
     )
  |> filter(
       fn: (r) =>
       r["_measurement"] == "utilities" and
       r["_field"] == "electricity_generation" or r["_field"] == "electricity_consumption"
     )
  |> drop(
       columns: [
         "_measurement",
         "_start",
         "_stop",
         "source"
       ]
     )
  |> pivot(
       rowKey:["_time"],
       columnKey: ["_field"],
       valueColumn: "_value"
     )
  |> derivative(
       unit: 1h,
       columns: [
        "electricity_generation",
        "electricity_consumption"
       ]
     )
  |> map(
       fn: (r) => (
         {
           "_time": r["_time"],
           "electricity_ratio": r["electricity_generation"] / r["electricity_consumption"]
         }
       )
     )

